# These are short Russian paraphrases for learning sedimentological vocabulary
# and reasoning discipline. Each item retains its source IDs and locators.
ITEMS = [
    ("core_required_metadata", "Какие сведения нужно фиксировать вместе с послойным описанием керна?", "Для каждого интервала связывай описание с площадью или месторождением, номером скважины, рейсом/долблением, интервалом отбора, выходом керна, номером и мощностью слоя. Записывай литологию по единой схеме. Это позволяет восстановить положение описанного слоя и сопоставить его с другими данными.", [(MSU, "PDF, с. 6-7")]),
    ("core_observation_fields", "Составь контрольный список макроскопических признаков, отмечаемых в керне.", "Отмечай название породы и видимые признаки: цвет и его равномерность, минеральный/обломочный состав, размер и форму зерен, структуру и текстуру, слоистость, включения, контакты, вторичные изменения, поры, каверны, трещины и признаки флюидов. Угол залегания и уверенность интерпретации записывай отдельно от наблюдений.", [(MSU, "PDF, с. 7"), (CCBY, "раздел 1")]),
    ("core_workflow", "Как выстроить описание керна, чтобы не потерять наблюдаемые детали?", "Сначала зафиксируй идентификацию и глубинный интервал, затем разбей керн на однородные слои по видимым границам. Для каждого слоя отдельно опиши литологию, состав, зернистость, текстуру, контакты и вторичные признаки. После описательной части формулируй генетическую интерпретацию и отмечай её уверенность.", [(MSU, "PDF, с. 6-7"), (BOOK, "гл. 1, с. 1-4")]),
    ("facies_definition", "Дай рабочее определение фации для описания керна.", "Фация — геологическое тело или часть слоя с определённым сочетанием литологических, текстурно-структурных и палеонтологических признаков. Для керна сначала описывают именно это сочетание. Название среды осадконакопления является интерпретацией и должно опираться на набор признаков, а не подменять описание.", [(BOOK, "гл. 1, с. 3-4")]),
    ("facies_association", "Что такое фациальная ассоциация и зачем она нужна?", "Фациальная ассоциация — группа генетически связанных фаций, совместно характеризующая осадочную обстановку. Она помогает перейти от отдельного слоя к реконструкции системы, но её следует обосновывать пространственными и вертикальными связями, а также независимыми данными.", [(BOOK, "гл. 1, с. 4")]),
    ("facies_model", "Что делает фациальную модель полезной, а не просто красивой схемой?", "Фациальная модель обобщает многочисленные данные о современных аналогах и древних отложениях для конкретной осадочной системы. Её надёжность зависит от репрезентативности примеров и от того, насколько модель учитывает процессы, изменения во времени и неопределённость. Новые наблюдения должны позволять уточнить модель.", [(BOOK, "гл. 1, с. 1-4; предисловие, с. xi-xii")]),
    ("observation_vs_interpretation", "Раздели прямое наблюдение и вывод о среде в примере: серый мелкозернистый песчаник с косой слоистостью.", "Наблюдения: порода серого цвета, мелкозернистая, песчаник; присутствует косая слоистость. Среда осадконакопления по этому описанию однозначно не определяется. Напиши гипотезу отдельно и проверь её по ассоциации текстур, контактам, соседним слоям, ихнофоссилиям, керну и данным ГИС/сейсмики.", [(BOOK, "гл. 1, с. 1-4"), (TEXTURE, "раздел о слоистости")]),
    ("core_and_cuttings", "Почему шлам хуже керна подходит для анализа осадочных текстур?", "При описании керна доступны слоистость, подошва и кровля слоя, стилолитовые швы и другие текстуры. Шлам обычно теряет исходные взаиморасположения и поверхности напластования; размеры и форма частиц могут изменяться при бурении. Поэтому интерпретацию по шламу ограничивают, а текстурный анализ по возможности ведут на непрерывном керне.", [(CCBY, "раздел «Текстура горных пород»")]),
    ("integrate_core_logs_seismic", "Какие данные лучше объединять, чтобы обосновать фациальную модель скважинного интервала?", "Объединяй макроописание керна и его интервальные границы с ГИС, стратиграфией, палеонтологией и сейсмическими данными. Керн даёт детальные признаки породы, ГИС помогает коррелировать интервалы между скважинами, а сейсмика — оценивать геометрию тел. Ни один из этих типов данных сам по себе не заменяет остальные.", [(BOOK, "гл. 1-4"), (RUNEFT, "разделы о моделях Самотлора и Тюменской свиты")]),
    ("color_limits", "Можно ли определять фацию только по цвету керна?", "Нет. Запиши наблюдаемый цвет и его неоднородность, но не выводи из них фацию без других оснований. Цвет может зависеть от состава, примесей, окисления, восстановления и последующих изменений. Проверь структуру, зернистость, контакты, включения и соседние слои.", [(MSU, "PDF, с. 7"), (CCBY, "раздел 1")]),
    ("grain_description", "Как корректно описать зернистость обломочной породы без лишней уверенности?", "Укажи наблюдаемый диапазон размера зерен и наиболее частую фракцию, если она различима; отдельно опиши сортировку, форму и окатанность обломков. Если размер виден только приблизительно, обозначь это. Не превращай визуальную оценку в точное гранулометрическое измерение.", [(CCBY, "раздел о структуре терригенных пород"), (MSU, "PDF, с. 7")]),
    ("bedding_description", "Что нужно записать при описании слоистости?", "Назови видимую морфологию: горизонтальная, волнистая, косоволнистая или косая; отметь масштаб и толщину слойков, их непрерывность, направление наклона, форму серийных швов и характер границ. Если поверхность керна ограничивает обзор, укажи, что текстура наблюдается лишь частично.", [(TEXTURE, "раздел о классификации слоистости"), (MSU, "PDF, с. 7")]),
    ("bedding_scale", "Как учитывать толщину слоёв при описании осадочной породы?", "Описывай толщину наблюдаемых слоёв и слойков численно или по принятой в проекте шкале. В одной из российских классификаций крупная слоистость соответствует слоям более 1 м, средняя — 10 см–1 м, мелкая — 1–10 см, а тонкая — менее 1 см. Указывай используемую схему: градации — классификационный ориентир, а не самостоятельная фациальная интерпретация.", [(BIGENC, "статья о слоистости; классификация по Ботвинкиной")]),
    ("bedding_scale_relevance", "Почему полезно измерять масштаб слоистости, а не писать только «слоистая»?", "Толщина и геометрия слойков помогают сопоставлять образцы и отличать внутреннюю слойчатость от более крупных границ пластов. Записывай фактически наблюдаемую толщину и тип текстуры. Масштаб сам по себе не указывает на конкретную среду, но делает описание проверяемым и пригодным для корреляции.", [(BIGENC, "статья о слоистости"), (MSU, "PDF, с. 7")]),
    ("horizontal_bedding", "Что можно и чего нельзя заключить по горизонтальной слоистости?", "Горизонтальная слоистость — наблюдаемое параллельное напластование. Она может соответствовать спокойному осаждению или режимам без выраженной донной миграции, но сама по себе не определяет конкретную среду. Учитывай гранулометрию, повторяемость слойков, биотурбацию и соседние фации.", [(TEXTURE, "раздел о типах слоистости")]),
    ("wavy_bedding", "Как описать волнистую слоистость и её возможное значение?", "Сначала опиши амплитуду и длину волны, симметрию, непрерывность слойков и наличие оползневых деформаций. Волнистая слоистость часто связана с колебательными движениями воды или воздуха у дна, но интерпретацию уточняют по масштабу, составу осадка и ассоциации текстур.", [(TEXTURE, "раздел о типах слоистости")]),
    ("cross_bedding", "Как описать косую слоистость, не приписывая ей сразу речное происхождение?", "Зафиксируй наклон слойков, направление и размер серий, форму их границ и смену направлений. Косая слоистость отражает направленное перемещение осадка, но встречается в разных обстановках — речной, приливной, дельтовой и эоловой. Для определения среды нужны дополнительные признаки и архитектура тел.", [(TEXTURE, "раздел о типах слоистости"), (BOOK, "гл. 7-11")]),
    ("interbedding", "Как описывать переслаивание песчаника и аргиллита?", "Запиши литологию каждого компонента, толщину и частоту слойков, резкость или постепенность контактов, характер слоистости и пропорцию песчаных и глинистых прослоев. Термин «ритмичное переслаивание» допустим при регулярном чередовании. Генетическую интерпретацию отложи до сопоставления с другими признаками.", [(MSU, "PDF, с. 7"), (BOOK, "гл. 10-12")]),
    ("bioturbation", "Как фиксировать биотурбацию в керне?", "Опиши плотность и размер ходов, их ориентацию, заполнение, степень разрушения первичной слоистости и положение относительно контакта. Если следы нельзя уверенно распознать, называй их предполагаемыми. Ихнофоссилии дают информацию о поведении организмов и условиях среды, но интерпретируются вместе с осадочными признаками.", [(BOOK, "гл. 4, с. 102-164")]),
    ("massive_texture", "Означает ли массивная текстура, что осадок накопился в одном конкретном режиме?", "Нет. «Массивная» означает, что видимая слоистость не выражена или не распознана на доступной поверхности. Такая текстура может иметь несколько причин, включая быстрое накопление, перемешивание или слабый контраст слоёв. Проверь свежесть поверхности, масштаб наблюдения и возможную биотурбацию.", [(BOOK, "гл. 1, с. 1-4"), (CCBY, "раздел о текстурах")]),
    ("erosional_contact", "Как описывать эрозионную подошву слоя?", "Отметь резкость и форму контакта, врезание в подстилающий слой, неровность, возможный базальный гравийно-галечный материал и обломки подстилающей породы. Разделяй наблюдаемую поверхность и вывод о размыве. Эрозионный контакт может ограничивать фациальную последовательность, но его значение зависит от регионального контекста.", [(BOOK, "гл. 1-2"), (MSU, "PDF, с. 7")]),
    ("contacts_and_breaks", "Почему поверхности перерыва важны для фациальной интерпретации?", "Эрозионные и иные поверхности перерыва могут отделять последовательности с разным составом и историей накопления. Их фиксируют по характеру контакта, следам размыва, конденсации, биотурбации или резкой смене пород. Поверхности сопоставляют по разрезу и не назначают им стратиграфическую роль только по фотографии одного керна.", [(BOOK, "гл. 1-2")]),
    ("facies_sequence", "Что такое фациальная последовательность в вертикальном разрезе?", "Это вертикальная смена фаций, при которой закономерно меняется один или несколько параметров: зернистость, доля песчаного материала, мощность слоёв или осадочные текстуры. Опиши наблюдаемый тренд вверх по разрезу и контакты, затем проверь возможные причины по соседним интервалам и корреляции.", [(BOOK, "гл. 1, с. 3-5")]),
    ("river_facies_groups", "Какие крупные аллювиальные фации обычно различают в пойме равнинной реки?", "В базовой схеме различают русловую, пойменную и старичную фации. Внутри поймы выделяют прирусловую часть и более удалённые участки. Это схема для упорядочивания наблюдений; реальные разрезы могут быть неполными, переотложенными или смешанными с другими процессами.", [(ALLUVIAL, "раздел об аллювиальных отложениях"), (BOOK, "гл. 7, с. 259-314")]),
    ("channel_vs_floodplain", "Какие признаки помогают отличить русловые от пойменных отложений?", "Русловые тела чаще представлены более грубым песчаным или гравийным материалом, косой слоистостью и локальными эрозионными подошвами. Пойменные интервалы чаще тонкозернистые и могут содержать тонкое переслаивание, корни или признаки почвообразования. Эти тенденции не универсальны: сравнивай комплекс признаков и положение в разрезе.", [(ALLUVIAL, "раздел об аллювиальных отложениях"), (BOOK, "гл. 7, с. 259-314")]),
    ("channel_base", "Какую роль может играть грубый материал у подошвы палеоруслового песчаного тела?", "Грубый базальный материал вместе с неровной врезанной подошвой может указывать на размыв и концентрацию более крупных обломков при заполнении русла. Однако такая подошва не обязательна и не уникальна для русла. Запиши размер и состав обломков, геометрию контакта и переход вверх.", [(BOOK, "гл. 7, с. 259-314"), (RUNEFT, "раздел о глубине и геометризации канала")]),
    ("fining_upward", "Всегда ли уменьшение зернистости вверх доказывает заполнение речного русла?", "Нет. Уменьшение зернистости вверх может соответствовать ослаблению потока и заполнению канала, но подобный тренд формируется и в других обстановках. Для русловой гипотезы ищи врезанную подошву, связанные косослоистые пески, латеральное наращивание и переход к пойменным осадкам; проверь альтернативы.", [(BOOK, "гл. 7, с. 259-314"), (ALLUVIAL, "раздел об аллювиальных отложениях")]),
    ("point_bar", "Какие признаки ожидаются у отложений прирусловой отмели или point bar?", "Для прирусловой отмели меандрирующей реки ожидаются песчаные тела латерального наращивания, косая слоистость и закономерные изменения зернистости. В вертикальном керне геометрия ограничена, поэтому не называй тело point bar только по косой слоистости; используй корреляцию, ориентированные данные и геометрию соседних скважин.", [(BOOK, "гл. 7, с. 259-314"), (RUNEFT, "раздел о меандрирующих системах")]),
    ("floodplain", "Как осторожно описать предполагаемые пойменные отложения?", "Запиши тонкозернистые алевритовые или глинистые прослои, характер напластования, корневые следы, палеопочвенные признаки и возможные органические остатки. Называй их пойменными только как гипотезу, если нет пространственной связи с русловыми телами и повторяемой фациальной ассоциации.", [(ALLUVIAL, "раздел об аллювиальных отложениях"), (BOOK, "гл. 7, с. 259-314")]),
    ("oxbow_fill", "Что может происходить при заполнении старичного озера и какие признаки искать?", "Старичный водоём после отделения от русла может заполняться тонким взвешенным материалом и органическим веществом; разрез способен переходить от более грубого руслового материала к тонким илам или глинам. В керне такой переход не уникален, поэтому проверяй органику, фауну, контакты и положение между русловыми песками.", [(ALLUVIAL, "раздел об аллювиальных отложениях"), (BOOK, "гл. 7, с. 259-314")]),
    ("levee_splay", "Как различать идеализированные отложения прируслового вала и прорывного конуса?", "Прирусловой вал формируется при выходе паводковой воды за берег и осаждении материала рядом с руслом; прорывной конус связан с локальным прорывом вала и может образовывать отдельное песчано-алевритовое тело на пойме. В керне различение требует пространственного положения и связи с каналом, а не одного зернового тренда.", [(ALLUVIAL, "описание элементов поймы"), (BOOK, "гл. 7, с. 259-314")]),
    ("river_planforms", "Какие типы речных систем сравниваются в фациальных моделях Западной Сибири?", "В опубликованном кейсе сравниваются спрямлённые, ветвящиеся, меандрирующие и анастомозирующие речные системы. Для них различаются геометрия руслового пояса и комплексы песчано-алевролитовых отложений. В конкретном разрезе тип системы выводили по совокупности керна, ГИС, палеотектонических реконструкций и сейсмических признаков.", [(RUNEFT, "раздел о среднеюрском комплексе")]),
    ("paleochannel_diagnosis", "Какие признаки вместе делают гипотезу палеорусла правдоподобнее?", "Сочетание врезанной подошвы, руслового песчаного или гравийно-песчаного тела, направленной косой слоистости, возможного уменьшения зернистости вверх и латеральных изменений поддерживает русловую гипотезу. Уверенность повышают межскважинная геометрия и согласование с ГИС/сейсмикой. Ни один отдельный признак не доказывает палеорусло.", [(BOOK, "гл. 7, с. 259-314"), (RUNEFT, "разделы о палеоруслах и речных системах")]),
    ("paleochannel_vs_tidal", "Как не перепутать речной канал с приливным каналом по косой слоистости?", "Косая слоистость встречается и в речных, и в приливных отложениях. Для приливной гипотезы дополнительно ищи двунаправленные наборы слойков, глинистые драпировки, флазерное/линзовидное переслаивание и признаки периодического затишья; для речной — контекст руслового вреза, латерального наращивания и связи с поймой. Сопоставь с геометрией тел и региональной обстановкой.", [(BOOK, "гл. 7, с. 259-314; гл. 11, с. 430-482"), (TEXTURE, "раздел о волнистой и косой слоистости")]),
    ("paleochannel_case_context", "Почему глубину и ширину палеорусла нельзя надёжно оценить по одному керну?", "Керн даёт локальную вертикальную выборку и обычно не показывает полную ширину тела. В примере по Западной Сибири тип речной системы и геометрию руслового пояса оценивали с использованием керна, ГИС, палеотектонических реконструкций и сейсмических данных. Размеры следует рассчитывать по геометрии и подходящим моделям для конкретного типа канала.", [(RUNEFT, "раздел о глубине канала и ширине руслового пояса")]),
    ("modern_analog_limit", "Как использовать современную реку как аналог древнего палеорусла?", "Современный аналог помогает понять процессы и возможные формы отложений, но не является точной копией древней системы. Сравнивай конкретные процессы, морфологию, гидродинамику и доступные данные; учитывай тектонику, климат, уровень моря и неполноту сохранения древнего разреза. Аналог формирует проверяемую гипотезу, а не готовый ответ.", [(BOOK, "гл. 1, с. 1-4; гл. 7, с. 259-314")]),
    ("uncertainty", "Как сообщить неопределённость при интерпретации фации?", "Отдели наблюдаемые признаки от генетического вывода. Назови основную гипотезу и коротко укажи, какие признаки её поддерживают, какие альтернативы остаются и каких данных не хватает. Не превращай условную интерпретацию по одному керновому фрагменту в утверждение о всей осадочной системе.", [(BOOK, "гл. 1-3"), (RUNEFT, "описание комплексирования данных")]),
    ("russian_case_core_work", "Что показывает российский пример макроскопической реконструкции среднеюрских отложений по керну?", "В опубликованной работе реконструкция строилась по послойному макроскопическому описанию керна нескольких скважин. В перечне признаков названы, среди прочего, мелкая косая слойчатость ряби, бугорчатая косая слоистость и градационная слоистость. Эти текстуры описывали в комплексе при восстановлении условий осадконакопления.", [(NEFTEGAZ, "описание результатов и перечисление текстур")]),
    ("delta_basics", "Какие элементы дельтовой системы полезно различать при описании керна?", "Различай распределительные каналы, прирусловые/естественные валы, прорывные тела, устьевые бары и более спокойные межканальные участки. Дельтовая система испытывает влияние речного, волнового и приливного процессов; потому одинаковая песчаная фация может иметь разное происхождение. Проверяй ассоциацию и положение относительно других элементов.", [(BOOK, "гл. 9, с. 346-393")]),
    ("aeolian", "Какая комбинация признаков поддерживает эоловую интерпретацию песчаника?", "Крупная косая слоистость, хорошо отсортированный песок, округлые зерна и набор текстур эоловых дюн могут поддерживать эоловую гипотезу. Но косая слоистость и хорошая сортировка встречаются и в других системах. Проверяй масштаб наборов, характер поверхностей, соседние фации и региональный контекст.", [(BOOK, "гл. 8, с. 315-345")]),
    ("tidal", "Какие текстурные признаки стоит проверить для приливно-отливных отложений?", "Проверь сочетание косой слоистости с противоположными направлениями миграции, глинистыми драпировками, флазерным, волнистым или линзовидным переслаиванием и поверхностями повторной активации. Такие признаки отражают периодические смены течений и затиший, но их интерпретация зависит от ассоциации и геометрии тела.", [(BOOK, "гл. 10-11, с. 394-482"), (TEXTURE, "раздел о косоволнистой и волнистой слоистости")]),
    ("storm_shoreface", "Что означает бугорчатая косая слоистость и как осторожно её трактовать?", "Бугорчатая косая слоистость может быть связана со штормовым перемещением осадка в мелководной морской зоне. Опиши её форму и положение в слое, затем проверь зернистость, морские признаки, биотурбацию и переходы к соседним фациям. Не используй одну текстуру как единственное доказательство штормовой обстановки.", [(BOOK, "гл. 12, с. 483-528"), (NEFTEGAZ, "пример описания текстур")]),
    ("turbidite", "Какие признаки поддерживают турбидитовую интерпретацию тонкозернистого песчаника?", "Ищи градационную слоистость, характерную последовательность текстур, подошвенные следы и связь с глубоководными тонкими отложениями. Турбидитовые слои часто неполные и изменённые, поэтому не требуй присутствия всех частей идеальной последовательности. Учитывай повторяемость слоёв и положение в подводном конусе выноса.", [(BOOK, "гл. 13, с. 529-587"), (NEFTEGAZ, "пример градационной слоистости")]),
    ("glacial", "Почему для ледниковых отложений недостаточно назвать породу плохо отсортированной?", "Плохая сортировка встречается в разных процессах. Для ледниковой гипотезы оценивай матрикс и диапазон обломков, сочетание несортированного материала с деформациями и поверхностями, а также связи с другими ледниковыми фациями. Обозначай литологию непосредственно; генезис устанавливай по комплексу признаков и геологическому контексту.", [(BOOK, "гл. 5, с. 165-219")]),
    ("volcaniclastic", "Как не принять любой тёмный обломочный слой за вулканогенно-обломочную породу?", "Тёмный цвет сам по себе не подтверждает вулканогенное происхождение. Сначала опиши размер и состав обломков, матрикс, сортировку, текстуру и контакты. Для генетической интерпретации требуются диагностические вулканические компоненты и согласование с положением слоя и ассоциацией пород.", [(BOOK, "гл. 6, с. 220-258"), (MSU, "PDF, с. 7")]),
    ("carbonate_description", "Какие признаки важны при макроскопическом описании карбонатного керна?", "Отмечай цвет, текстуру, видимые скелетные или обломочные компоненты, размер зерен, долю микритового матрикса, цемент, поры, трещины, стилолиты и признаки диагенетических изменений. Макроскопическое описание не заменяет петрографию: если компоненты неразличимы, укажи пределы видимости и не назначай микрофацию без шлифа.", [(BOOK, "гл. 14-18, с. 588-820"), (MSU, "PDF, с. 7")]),
    ("reef", "Чем рифовая постройка отличается от обычного слоя ракушечного известняка?", "Рифовая постройка — биологически сооружённый рельеф, который формирует массивное тело и связан с окружающими слоистыми отложениями. Ракушечный или биокластовый слой сам по себе не доказывает наличие рифа: учитывай каркасные организмы, характер роста, геометрию постройки и фации её обрамления.", [(BOOK, "гл. 17, с. 713-767")]),
    ("evaporite", "Как формируются эвапориты и какие ограничения есть у диагностики по одному кристаллу?", "Эвапориты — химические осадки, формирующиеся из рассолов при значительном дефиците водного баланса и испарительном концентрировании. Кристалл или белая окраска сами по себе недостаточны для уверенного определения породы и среды. Учитывай минеральный состав, текстуру, ассоциацию с карбонатами/глинами и признаки последующего растворения или замещения.", [(BOOK, "гл. 19, с. 821-910")]),
    ("sea_level_surfaces", "Какие поверхности особенно важны в секвенс-стратиграфической интерпретации?", "В книге обсуждаются поверхности регрессивной эрозии, трансгрессивные поверхности и поверхности максимального затопления. В разрезе описывай наблюдаемые признаки контакта, смену литологии и возможный перерыв, а затем связывай поверхность с региональной корреляцией. Одного кернового кадра недостаточно для надёжного определения её стратиграфического ранга.", [(BOOK, "гл. 2, с. 35-58")]),
    ("core_photo_scale", "Что важно учитывать, когда текстуру оценивают только по фотографии керна?", "Фотография показывает цвет и форму лишь при известном масштабе, освещении, ориентации и качестве поверхности. Без линейки нельзя надёжно оценить миллиметровый размер; без ориентации керна наклон слойков может быть неоднозначен. Если граница или текстура скрыта, зафиксируй это и не заполняй пропуск догадкой.", [(MSU, "PDF, с. 6-7"), (BOOK, "гл. 3, с. 59-101")]),
    ("depth_consistency", "Как проверять границы интервалов в структурированном описании?", "Для каждого сегмента указывай верхнюю и нижнюю глубину в одной системе единиц и следи, чтобы нижняя граница была больше верхней. Интервалы должны совпадать с фото/керном и не перекрываться случайно. Если часть глубины не описана или граница приблизительна, сохрани пробел или пометь неопределённость, а не придумывай точную цифру.", [(MSU, "PDF, с. 6-7"), (BOOK, "гл. 3, с. 59-101")]),
    ("machine_description_schema", "Опиши роль VLM в макроописании керна в рамках этого проекта.", "VLM должна формировать стандартизированное русскоязычное описание видимых интервалов: глубины, литология и наблюдаемые признаки. Среду осадконакопления, фацию и уверенность следует выдавать отдельно и только когда для этого есть достаточные данные. Сегментация границ YOLO и текстовое описание VLM — разные задачи, которые затем объединяются.", [(MSU, "PDF, с. 6-7"), (BOOK, "гл. 1-3")]),
    ("text_only_role", "Может ли текстовый пример без фотографии быть полезен для обучения VLM?", "Да. Текстовые примеры помогают усвоить русскую терминологию, структуру ответа, различие между наблюдением и интерпретацией и правила осторожного вывода. Но без фотографии они не учат связывать конкретную текстуру с пикселями и не являются визуальной разметкой фации. Для распознавания по изображению нужны отдельные проверенные фотоописания.", [(BOOK, "гл. 1-4"), (MSU, "PDF, с. 6-7")]),
    ("no_evidence_answer", "Как ответить, если фотография не позволяет определить обстановку осадконакопления?", "Опиши только различимые признаки и прямо укажи, что среда по этому изображению не определяется. Перечисли, какие дополнительные данные нужны: соседние интервалы керна, описание контактов, ГИС, ориентировка, палеонтология или межскважинная корреляция. Не выбирай фацию ради заполнения поля.", [(BOOK, "гл. 1-4"), (MSU, "PDF, с. 7")]),
    ("russian_response", "На каком языке отвечать и как поступать с англоязычным источником?", "Отвечай по-русски. Англоязычные названия и сокращения можно привести в скобках, если они помогают связать термин с первоисточником. Перевод целевой подписи не делай автоматической заменой исходной: сохраняй оригинал и проверяй геологические термины и интервалы.", [(BOOK, "источник русскоязычного проекта"), ("usgs_existing_public_core_datasets", "проектный манифест внешних источников")]),
    ("review_before_visual_training", "Какие подписи безопасно использовать как целевые фотоописания при дообучении?", "Используй только описания, для которых подтверждены фото, глубинный интервал и соответствие тексту источника; целевые признаки должны быть проверены геологом или пользователем. Машинный OCR и автоматическое сопоставление фото с логом остаются кандидатами до проверки и не должны смешиваться с утверждённой разметкой.", [(MSU, "PDF, с. 6-7"), ("usgs_existing_public_core_datasets", "data/external_manifest.json")]),
    ("facies_confidence", "Как присвоить уверенность гипотезе о фации?", "Уверенность должна отражать полноту и согласованность независимых признаков, масштаб изображения, сохранность керна и поддержку со стороны ГИС/сейсмики/палеонтологии. Ставь низкую уверенность, если вывод основан на одном признаке или границы неясны. Высокая уверенность по одному снимку без контекста не обоснована.", [(BOOK, "гл. 1-4"), (RUNEFT, "описание комплексирования источников данных")]),
    ("paleochannel_nonunique", "Какие похожие обстановки могут дать песчаное тело с косой слоистостью?", "Русловые, приливные, дельтовые, эоловые и некоторые мелководно-морские системы могут формировать песчаные тела с косой слоистостью. Различай их по сочетанию направлений течения, глинистых драпировок, эрозионной подошвы, биотурбации, зерновых трендов, геометрии тел и соседних фаций.", [(BOOK, "гл. 7-12"), (TEXTURE, "раздел о косой слоистости")]),
    ("description_not_genesis", "Перепиши фразу «русловой песок» в нейтральное описание, если генезис не доказан.", "Нейтральный вариант: «Песчаник светло-серый, мелко- и среднезернистый, с косой слоистостью; подошвенный контакт неровный, в основании отмечены редкие гравийные обломки». Термин «русловой» вынеси в отдельную гипотезу и обоснуй ассоциацией признаков.", [(MSU, "PDF, с. 7"), (BOOK, "гл. 1, с. 1-4")]),
    ("core_completeness", "Почему выход керна и его сохранность нужно учитывать при реконструкции?", "Неполный выход и механическое разрушение могут удалить тонкие прослои, размытые контакты или верхнюю часть последовательности. При описании фиксируй пропуски, трещиноватость и состояние материала. Интерпретация последовательности должна учитывать, что сохранённый керн может представлять лишь часть исходного разреза.", [(MSU, "PDF, с. 6-7"), (BOOK, "гл. 3, с. 59-101")]),
    ("modern_analogue_question", "Что общего и в чём ограничение сравнения современного аналога с палеоруслом?", "Сходство позволяет сопоставить процессы переноса, формы русла и наборы современных осадков с древними фациями. Ограничение в том, что климат, расход, растительность, тектоника, базис эрозии и сохранение осадков могли быть другими. Поэтому аналог помогает строить проверяемую модель, но не доказывает интерпретацию без данных древнего разреза.", [(BOOK, "гл. 1, с. 1-4; гл. 7, с. 259-314")]),
    ("digital_core_documentation", "Какую роль играют фотографии и цифровые колонки в современной документации керна?", "Фотографии и цифровые колонки помогают оперативно сохранять непрерывную документацию, привязывать описание к глубине и сравнивать интервалы. Методические материалы Роснедр отмечают использование фотодокументации, электронных устройств и шаблонов геологических колонок. Такой цифровой формат не отменяет проверки глубин и качества геологического описания.", [("rosnedra_vims_core_documentation_2024", "официальное сообщение Роснедр от 18.01.2024")]),
    ("facies_model_west_siberia", "Как в кейсе Западной Сибири строили фациальную модель русловых систем?", "В опубликованном примере сочетали керн, ГИС, палеотектонические реконструкции и спектральную декомпозицию сейсмики. По комплексу данных выделяли тип речной системы и оценивали геометрию русла и руслового пояса. Макрофации керна затем использовали как опорные признаки для интерпретации скважин без керна.", [(RUNEFT, "раздел о среднеюрском комплексе и этапе распознавания макрофаций")]),
    ("intrinsic_vs_postdepositional", "Как учитывать вторичные изменения, не смешивая их с первичной текстурой?", "Сначала опиши первичные признаки напластования и осадка, затем отдельно перечисли трещины, стилолиты, цементацию, растворение, перекристаллизацию, окисление или другие изменения. Если вторичные процессы стёрли первичную текстуру, так и укажи. Не приписывай постседиментационные признаки энергии или направлению древнего потока.", [(MSU, "PDF, с. 7"), (BOOK, "гл. 14-19")]),
    ("image_answer_json", "Какой минимальный формат ответа использовать для фотоописания нескольких интервалов?", "Верни JSON с массивом description_segments. Для каждого наблюдаемого сегмента укажи top_m, base_m и нейтральное русское description. Не добавляй фацию или среду осадконакопления в текст литологического описания, если вывод не запрошен или не обеспечен контекстом.", [("user_approved_core_photodescriptions", "4 подтверждённые без перевода записи; data/qwen3_vl_v3_reviewed_pilot.jsonl")]),
]


def write_jsonl(path: Path, records: list[dict]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="\n") as stream:
        for record in records:
            stream.write(json.dumps(record, ensure_ascii=False) + "\n")


def main() -> None:
    text_records = []
    for record_id, question, answer, source_refs in ITEMS:
        text_records.append({
            "conversations": [
                {"from": "human", "value": question},
                {"from": "gpt", "value": answer},
            ],
            "metadata": {
                "record_id": f"knowledge_{record_id}",
                "record_type": "text_only_knowledge",
                "review_status": "curated_reference_synthesis",
                "training_approved": True,
                "geology_approved": False,
                "approval_basis": "User requested Russian text-only geology knowledge to be used for local Qwen training; answer is a short reference-based paraphrase, not a photo-derived label.",
                "target_language": "ru",
                "sources": [
                    {"source_id": source_id, "locator": locator}
                    for source_id, locator in source_refs
                ],
            },
        })
    write_jsonl(TEXT_OUTPUT, text_records)

    visual_records = [
        json.loads(line)
        for line in VISUAL_INPUT.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    approvals = {
        row["record_id"]: row
        for row in (
            json.loads(line)
            for line in APPROVAL_INPUT.read_text(encoding="utf-8").splitlines()
            if line.strip()
        )
    }
    verified_visual_records = []
    translation_pending_records = 0
    for item in visual_records:
        metadata = item.get("metadata", {})
        record_id = metadata.get("record_id")
        approval = approvals.get(record_id)
        target_text = item["conversations"][1]["value"]
        target_hash = hashlib.sha256(target_text.encode("utf-8")).hexdigest()
        if not approval or approval.get("target_sha256") != target_hash:
            raise SystemExit(f"Missing exact user approval for visual record: {record_id}")
        if approval.get("decision") == "geology_approved_translation_pending":
            translation_pending_records += 1
            continue
        if approval.get("decision") != "approved_unchanged":
            raise SystemExit(f"Unrecognized visual approval decision for: {record_id}")
        metadata.update({
            "training_approved": True,
            "review_status": "approved_unchanged_by_user_hash_verified",
            "approved_by": approval.get("approved_by"),
            "approved_at": approval.get("approved_at"),
            "approval_basis": approval.get("basis"),
        })
        verified_visual_records.append(item)
    if not verified_visual_records or not all(
        item.get("metadata", {}).get("geology_approved") is True
        for item in verified_visual_records
    ):
        raise SystemExit("Visual manifest must contain only user/geologist-confirmed examples.")
    visual_records = verified_visual_records
    mixed_records = visual_records + text_records
    write_jsonl(MIXED_OUTPUT, mixed_records)
    summary = {
        "text_only_records": len(text_records),
        "user_confirmed_image_text_records": len(visual_records),
        "excluded_translation_pending_records": translation_pending_records,
        "total_records": len(mixed_records),
        "text_training_file": str(TEXT_OUTPUT.relative_to(PROJECT)),
        "mixed_manifest": str(MIXED_OUTPUT.relative_to(PROJECT)),
        "nonapproved_external_photo_log_candidates_included": 0,
    }
    (KNOWLEDGE_DIR / "training_data_summary.json").write_text(
        json.dumps(summary, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )
    print(json.dumps(summary, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
